// 2024年6月8日
// 一种牛顿分形
// from:
// 

vec2 mul(vec2 a, vec2 b){return vec2(a.x*b.x-a.y*b.y, a.x*b.y+a.y*b.x);}
vec2 div(vec2 a, vec2 b){return vec2(a.x*b.x+a.y*b.y, a.y*b.x-a.x*b.y)/dot(b,b);}
void mainImage(out vec4 O, vec2 U)
{
        vec2 R  = iResolution.xy,
             z  = 2.*(U+U - R) / R.y,
             z2,z3,z4,up,dw;
        float i;
        for(;i++<128.;)
        {
                z2 = mul(z,z);
                z3 = mul(z2,z);
                z4 = mul(z3,z);
                up = (3.*z4 +2.*z3 + z + vec2(60,0))*vec2(.95,1);
                dw = (4.*z3+vec2(1,3)*z2+vec2(10,0))*vec2(.81,1);
                z  = div(up,dw);
                vec4 e = vec4(z-1.,z-2.);
                if((e.x<.05 && e.x>-.1) || 
                   (e.y<.05 && e.y>-.1) ||
                   (e.z<.05 && e.z>-.1) ||
                   (e.w<.05 && e.w>-.1) )break;
        }
        O = i/256.*vec4(18,4,1,1);
}
